import {products} from './products.js';
import {unitPrice,cartTotals} from './commerce.js';
import {escapeHtml as e,icon} from './ui.js';
import {assetUrl} from './site.js';

const image = (src,alt,cls='',eager=false) => `<img src="${e(assetUrl(src))}" alt="${e(alt)}" class="${cls}" width="900" height="1100" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
export function productCard(p,c) {
  return `<article class="product-card"><div class="product-media"><a href="${c.url('product',p.id)}">${image(p.image,`${p.name}. ${p.composition[c.locale]}`)}</a>${p.featured===1?`<span class="product-tag">${c.t('home.collection')}</span>`:''}<button class="quick-add" data-add="${p.id}" aria-label="${e(c.t('product.add'))}: ${e(p.name)}">${icon('plus')}</button></div><div class="product-info"><div><h3><a href="${c.url('product',p.id)}">${e(p.name)}</a></h3><p>${c.t(`category.${p.category}`)}</p></div><div class="product-price">${c.money(p.price)}</div></div></article>`;
}
export function intro(c,key,description='') {
  return `<div class="page-intro"><nav class="breadcrumbs" aria-label="${c.t('common.home')}"><a href="${c.url('home')}">${c.t('common.home')}</a><span>/</span><span>${c.t(key)}</span></nav><h1>${c.t(key)}</h1>${description?`<p>${c.t(description)}</p>`:''}</div>`;
}
export function renderHome(c) {
  const occasions = [['love','heart'],['birthday','sun'],['home','leaf'],['thanks','gift']];
  return `<div class="hero-shell">${c.header()}<section class="hero"><div class="hero-copy"><p class="eyebrow">${icon('flower')}${c.t('hero.eyebrow')}</p><h1>${c.t('hero.title')}</h1><p class="hero-description">${c.t('hero.description')}</p><div class="hero-actions"><a class="button light" href="${c.url('shop')}">${c.t('hero.cta')}${icon('arrow')}</a><a class="text-link hero-secondary" href="${c.url('story')}">${c.t('hero.secondary')}</a></div><p class="hero-note">${icon('flower')}${c.t('hero.note')}</p></div><div class="hero-image-wrap">${image('/assets/hero.webp',c.t('hero.imageAlt'),'hero-image',true)}<div class="hero-stamp"><div>${icon('flower')}<span>${c.t('hero.side')}</span></div></div><p class="hero-caption">${icon('flower')}${c.t('hero.caption')}</p></div></section><div class="hero-bottom"><span>${icon('leaf')}${c.t('home.benefit1Title')}</span><span>${icon('gift')}${c.t('home.benefit2Title')}</span><span>${icon('heart')}${c.t('home.benefit3Title')}</span></div></div>
  <section class="section home-products"><div class="section-heading"><div><span class="overline">${c.t('home.collection')}</span><h2>${c.t('home.collectionTitle')}</h2><p>${c.t('home.collectionDescription')}</p></div><a href="${c.url('shop')}" class="text-link">${c.t('common.viewAll')}${icon('arrow')}</a></div><nav class="collection-categories" aria-label="${c.t('shop.category')}">${['bouquets','arrangements','gifts'].map(k=>`<a href="${c.url('shop')}?category=${k}">${c.t(`category.${k}`)}</a>`).join('')}</nav><div class="product-grid">${products.slice(0,3).map(p=>productCard(p,c)).join('')}</div><div class="occasion-bar" id="occasions"><h3>${c.t('home.occasionsTitle')}</h3><div class="occasion-links">${occasions.map(([k,i])=>`<a class="occasion-pill" href="${c.url('shop')}?occasion=${k}">${icon(i)}${c.t(`occasion.${k}`)}</a>`).join('')}</div></div></section>
  <section class="editorial">${image('/assets/atelier.webp',c.t('story.imageAlt'),'editorial-image')}<div class="editorial-copy"><span class="overline">Floricultura</span><h2>${c.t('home.storyTitle')}</h2><p>${c.t('home.storyText')}</p><a href="${c.url('story')}" class="text-link">${c.t('home.storyCta')}${icon('arrow')}</a></div></section>
  <section class="seasonal"><div class="seasonal-copy"><span class="overline">${c.t('hero.eyebrow')}</span><h2>${c.t('home.seasonTitle')}</h2><p>${c.t('home.seasonText')}</p><a class="button light" href="${c.url('shop')}?color=mixed">${c.t('home.seasonCta')}${icon('arrow')}</a></div>${image('/assets/bouquet-wild.webp',products[4].description[c.locale])}</section>
  <section class="section benefits">${[1,2,3].map((n)=>`<div class="benefit">${icon(['leaf','gift','flower'][n-1])}<div><h3>${c.t(`home.benefit${n}Title`)}</h3><p>${c.t(`home.benefit${n}Text`)}</p></div></div>`).join('')}</section>`;
}
export function renderShop(c) {
  const field = (key,values) => `<label class="filter-field"><span>${c.t(`shop.${key}`)}</span><select name="${key}" data-filter="${key}">${values.map(k=>`<option value="${k==='all'?'':k}">${c.t(`${key==='category'?'category':key}.${k}`)}</option>`).join('')}</select></label>`;
  return `${intro(c,'shop.title','shop.description')}<section class="shop-layout"><div class="shop-toolbar"><label class="search-field">${icon('search')}<span class="sr-only">${c.t('shop.search')}</span><input type="search" id="catalog-search" placeholder="${e(c.t('shop.searchPlaceholder'))}" maxlength="100" aria-label="${e(c.t('shop.search'))}"></label><label class="sort-field">${c.t('shop.sort')}<select id="sort">${['featured','priceAsc','priceDesc','newest'].map(k=>`<option value="${k}">${c.t(`shop.${k}`)}</option>`).join('')}</select></label></div><div class="shop-content"><aside class="filters"><h2>${c.t('shop.filters')}</h2>${field('category',['all','bouquets','arrangements','gifts'])}${field('color',['all','pink','white','burgundy','yellow','mixed'])}${field('occasion',['all','birthday','love','home','thanks','wedding'])}${field('price',['all','low','mid','high'])}<button data-reset-filters class="text-link">${c.t('shop.reset')}</button></aside><div class="shop-results" id="shop-results" aria-live="polite"></div></div></section>`;
}
export function renderProduct(p,c,size='classic',quantity=1) {
  return `<div class="product-page"><nav class="breadcrumbs" aria-label="${c.t('common.home')}"><a href="${c.url('home')}">${c.t('common.home')}</a><span>/</span><a href="${c.url('shop')}">${c.t('nav.shop')}</a><span>/</span><span>${e(p.name)}</span></nav><div class="product-detail"><div class="gallery"><button class="gallery-open" data-gallery="${p.id}" aria-label="${e(c.t('product.gallery',{name:p.name}))}">${image(p.image,p.composition[c.locale],'gallery-main',true)}</button><div class="gallery-thumbs"><button class="gallery-thumb" data-gallery="${p.id}" aria-label="${e(c.t('product.gallery',{name:p.name}))}">${image(p.image,p.name)}</button></div></div><section class="product-copy"><span class="overline">${c.t(`category.${p.category}`)}</span><h1>${e(p.name)}</h1><p class="price" id="product-price">${c.money(unitPrice(p,size))}</p><p class="stock">${c.t(p.available?'product.availability':'product.soldOut')}</p><p class="product-description">${e(p.description[c.locale])}</p><p class="composition">${e(p.composition[c.locale])}</p><p>${c.t('product.size')}</p><div class="size-options">${['classic','grand'].map(s=>`<button class="size-option" data-size="${s}" aria-pressed="${s===size}">${c.t(`product.${s}`)}<small>${c.money(unitPrice(p,s))}</small></button>`).join('')}</div><label class="field">${c.t('product.message')}<textarea id="gift-message" maxlength="180" placeholder="${e(c.t('product.messagePlaceholder'))}" rows="2"></textarea><small id="message-count">0 / 180</small><small>${c.t('product.messagePrivacy')}</small></label><div class="product-buy">${quantityControl(quantity,c,'product')}<button class="button" data-add-product="${p.id}">${c.t('product.add')}${icon('bag')}</button></div><div class="product-accordions"><details><summary>${c.t('product.delivery')}${icon('plus')}</summary><p>${c.t('product.deliveryText')}</p><a class="text-link" href="${c.url('policies')}">${c.t('footer.deliveries')}</a></details><details><summary>${c.t('product.care')}${icon('plus')}</summary><p>${c.t('product.careText')}</p></details></div></section></div></div><section class="section related"><div class="section-heading"><h2>${c.t('product.related')}</h2></div><div class="product-grid">${products.filter(x=>x.id!==p.id).slice(0,3).map(x=>productCard(x,c)).join('')}</div></section><dialog id="gallery-dialog"><button class="icon-button gallery-close" aria-label="${e(c.t('nav.close'))}" data-close-gallery>${icon('close')}</button>${image(p.image,p.composition[c.locale])}</dialog>`;
}
export function quantityControl(quantity,c,id) {
  return `<div class="quantity-control"><button type="button" data-quantity-minus="${id}" aria-label="${e(c.t('common.decrease'))}">${icon('minus')}</button><input type="number" min="1" max="20" value="${quantity}" data-quantity="${id}" aria-label="${e(c.t('common.quantity'))}"><button type="button" data-quantity-plus="${id}" aria-label="${e(c.t('common.increase'))}">${icon('plus')}</button></div>`;
}
export function summary(c,delivery='pickup',checkout=false) {
  const totals = cartTotals(c.cart,products,delivery);
  return `<aside class="order-summary"><h2>${c.t('checkout.review')}</h2>${checkout?`<div class="checkout-products">${c.cart.map(item=>{const p=products.find(x=>x.id===item.id);return `<p><span>${item.quantity} × ${e(p.name)} · ${c.t(`product.${item.size}`)}</span><span>${c.money(unitPrice(p,item.size)*item.quantity)}</span></p>`;}).join('')}</div>`:''}<div class="summary-line"><span>${c.t('common.subtotal')}</span><span>${c.money(totals.subtotal)}</span></div>${checkout?`<div class="summary-line"><span>${c.t('checkout.shipping')}</span><span>${totals.shipping?c.money(totals.shipping):c.t('common.free')}</span></div>`:''}<div class="summary-line total"><span>${c.t('common.total')}</span><strong>${c.money(totals.total)}</strong></div>${!checkout?`<a class="button" href="${c.url('checkout')}">${c.t('cart.checkout')}${icon('arrow')}</a>`:''}<p class="summary-note">${c.t(checkout?'checkout.freeShipping':'cart.shippingNote')}</p></aside>`;
}
export function renderCart(c) {
  if(!c.cart.length) return `${intro(c,'cart.title')}<div class="empty-state">${icon('bag')}<h2>${c.t('cart.empty')}</h2><p>${c.t('cart.emptyText')}</p><a class="button" href="${c.url('shop')}">${c.t('common.backShop')}${icon('arrow')}</a></div>`;
  return `${intro(c,'cart.title')}<section class="cart-layout"><div>${c.cart.map((item,index)=>{const p=products.find(x=>x.id===item.id);return `<article class="cart-row"><a href="${c.url('product',p.id)}">${image(p.image,p.name)}</a><div><h2><a href="${c.url('product',p.id)}">${e(p.name)}</a></h2><p>${c.t(`product.${item.size}`)}</p>${item.message?`<p class="cart-row-message">${e(item.message)}</p>`:''}${quantityControl(item.quantity,c,index)}<button class="remove-button" data-remove="${index}">${c.t('common.remove')}</button></div><p class="cart-row-price">${c.money(unitPrice(p,item.size)*item.quantity)}</p></article>`;}).join('')}<a class="text-link" href="${c.url('shop')}">${c.t('common.backShop')}</a></div>${summary(c)}</section>`;
}
export function field(c,name,type='text',extra='') {
  return `<label class="field" data-field="${name}"><span>${c.t(`checkout.${name}`)}</span><input type="${type}" name="${name}" id="field-${name}" maxlength="${type==='email'?254:100}" ${extra} aria-describedby="error-${name}"><span class="field-error" id="error-${name}"></span></label>`;
}
export function renderCheckout(c) {
  if(!c.cart.length) return renderCart(c);
  return `${intro(c,'checkout.title','checkout.description')}<section class="cart-layout"><form id="checkout-form" class="checkout-form" novalidate><div class="form-grid">${field(c,'name','text','autocomplete="name" required')}${field(c,'email','email','autocomplete="email" required')}${field(c,'phone','tel','autocomplete="tel" required')}</div><h2>${c.t('checkout.delivery')}</h2><div class="delivery-options"><label class="delivery-option"><input type="radio" name="delivery" value="pickup" checked>${c.t('checkout.pickup')}</label><label class="delivery-option"><input type="radio" name="delivery" value="local">${c.t('checkout.local')}</label></div><div class="form-grid" id="delivery-fields" hidden>${field(c,'postal','text','inputmode="numeric" autocomplete="postal-code"')}${field(c,'city','text','autocomplete="address-level2"')}${field(c,'address','text','autocomplete="street-address"')}${field(c,'number','text','autocomplete="off"')}</div><label class="field">${c.t('checkout.notes')}<textarea name="notes" maxlength="400" rows="3"></textarea></label><label class="consent"><input type="checkbox" name="consent" required aria-describedby="error-consent"><span>${c.t('checkout.consent')}</span></label><p class="field-error" id="error-consent"></p><button type="submit" class="button">${c.t('checkout.submit')}${icon('arrow')}</button></form><div id="checkout-summary">${summary(c,'pickup',true)}</div></section>`;
}
export function renderSuccess(c,delivery='pickup') {
  return `<section class="success-state">${icon('check')}<h1>${c.t('checkout.successTitle')}</h1><p>${c.t('checkout.successText')}</p><a href="${c.url('cart')}" class="button">${c.t('cart.title')}${icon('arrow')}</a></section><section class="review-summary" id="checkout-summary" data-delivery="${delivery==='local'?'local':'pickup'}">${summary(c,delivery,true)}</section>`;
}
export function renderInstitutional(key,c) {
  if(key==='story') return `${intro(c,'story.title','story.intro')}<section class="story-hero">${image('/assets/atelier.webp',c.t('story.imageAlt'))}<div><h2>${c.t('story.heading')}</h2><p>${c.t('story.body')}</p><p>${c.t('story.valuesText')}</p><p><a class="text-link" href="${c.url('shop')}">${c.t('common.viewAll')}${icon('arrow')}</a></p></div></section>`;
  if(key==='faq') return `${intro(c,'faq.title')}<section class="faq-list">${[1,2,3,4,5].map(n=>`<details><summary>${c.t(`faq.q${n}`)}${icon('plus')}</summary><p>${c.t(`faq.a${n}`)}</p></details>`).join('')}</section>`;
  if(key==='contact') return `${intro(c,'contact.title','contact.description')}<section class="contact-layout">${image('/assets/bouquet-gift.webp',products[5].description[c.locale],'contact-art')}<div><form id="contact-form" novalidate>${field(c,'name','text','autocomplete="name" required')}${field(c,'email','email','autocomplete="email" required')}<label class="field">${c.t('contact.subject')}<input name="subject" maxlength="100"></label><label class="field" data-field="message">${c.t('contact.message')}<textarea name="message" required maxlength="1000" rows="5" aria-describedby="error-message"></textarea><span class="field-error" id="error-message"></span></label><button type="submit" class="button">${c.t('contact.submit')}${icon('arrow')}</button></form><div id="contact-success" role="status" tabindex="-1" hidden>${icon('check')}<p>${c.t('contact.success')}</p><p id="contact-preview" class="message-preview"></p></div></div></section>`;
  const sections={policies:['delivery','returns','season'],privacy:['local','contact'],terms:['demo','images']};
  if(sections[key]) return `${intro(c,`${key}.title`,`${key}.intro`)}<article class="text-page">${sections[key].map(s=>`<section><h2>${c.t(`${key}.${s}Title`)}</h2><p>${c.t(`${key}.${s}Text`)}</p></section>`).join('')}</article>`;
  return `<section class="empty-state">${icon('flower')}<h1>${c.t('notFound.title')}</h1><p>${c.t('notFound.description')}</p><a class="button" href="${c.url('shop')}">${c.t('common.backShop')}${icon('arrow')}</a></section>`;
}
